SourceCode.Declaration:
/// <summary>
/// Modules switched off in the handheld app (Mobile module switches, Setup), for every worker and
/// device - to stop a broken module until a fixed app is installed. AppVersions limits it to the
/// listed versions (comma separated, e.g. 1.1.35,1.1.36); blank means every version. The app
/// picks it up within a few minutes and keeps the last answer for when it is offline.
/// </summary>
public class HSMobileOpsModuleSwitch extends common
{
}

Method.Source:
/// <summary>
/// The modules switched off for app version _appVersion: Disabled, with AppVersions blank
/// (every version) or listing it. Rows of HSMobileOpsModuleSwitchRow, element names.
/// </summary>
public static List disabledFor(str _appVersion)
{
    HSMobileOpsModuleSwitch   moduleSwitch;
    HSMobileOpsModuleSwitchRow row;
    List                      rows = new List(Types::Class);
    str                       versions;

    while select moduleSwitch
        where moduleSwitch.Disabled == NoYes::Yes
    {
        versions = strRem(moduleSwitch.AppVersions, ' ');
        if (versions && (!_appVersion || !strScan(',' + versions + ',', ',' + _appVersion + ',', 1, strLen(versions) + 2)))
        {
            continue;
        }
        row = new HSMobileOpsModuleSwitchRow();
        row.parmModule(enum2Symbol(enumNum(HSMobileOpsModule), moduleSwitch.Module));
        row.parmMessage(moduleSwitch.Message);
        rows.addEnd(row);
    }
    return rows;
}
